import{_ as e,o as n,c as s,O as t}from"./chunks/framework.57749cb7.js";const b=JSON.parse('{"title":"前端 AI 应用","description":"前端 AI 应用开发：流式输出与通信、AI 应用安全与合规。从「后端接模型」到「前端把它做成能用的产品」这一段。","frontmatter":{"description":"前端 AI 应用开发：流式输出与通信、AI 应用安全与合规。从「后端接模型」到「前端把它做成能用的产品」这一段。"},"headers":[],"relativePath":"frontend/AI/index.md","filePath":"frontend/AI/index.md","lastUpdated":1793331306000}'),r={name:"frontend/AI/index.md"};function l(o,a,p,i,d,c){return n(),s("div",null,a[0]||(a[0]=[t(`<h1 id="前端-ai-应用" tabindex="-1">前端 AI 应用 <a class="header-anchor" href="#前端-ai-应用" aria-label="Permalink to &quot;前端 AI 应用&quot;">​</a></h1><blockquote><p>后端接上模型只是第一步。真正决定体验的是前端这几件事：<strong>字能不能一个字一个字出来、断了能不能续、生成到一半能不能停、安不安全</strong>。 这个目录收的就是「前端做 AI 产品」的那层工程问题。</p></blockquote><h2 id="已收录" tabindex="-1">已收录 <a class="header-anchor" href="#已收录" aria-label="Permalink to &quot;已收录&quot;">​</a></h2><table><thead><tr><th>篇</th><th>讲什么</th><th>读完能解决</th></tr></thead><tbody><tr><td><a href="./01-流式输出与通信">01 流式输出与通信</a></td><td>SSE 与 fetch 读流、增量解析、断流续传、中断重试、流式 Markdown 渲染</td><td>「回答十几个字才蹦出来一次」「长回答被截断」「中文乱码」「生成到一半没法停」</td></tr><tr><td><a href="./02-AI应用安全与合规">02 AI 应用安全与合规</a></td><td>Prompt 注入（直接与间接）、工具调用越权、多租户隔离、内容审核、数据出境</td><td>「模型被一句话说服就把数据交出去了」「检索到了别人的文档」「上线被合规卡住」</td></tr></tbody></table><h2 id="和后端那部分的分工" tabindex="-1">和后端那部分的分工 <a class="header-anchor" href="#和后端那部分的分工" aria-label="Permalink to &quot;和后端那部分的分工&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">后端（knowledge/backend/AI-Agent）   前端（本目录）</span></span>
<span class="line"><span style="color:#e1e4e8;">─────────────────────────────────────────────────</span></span>
<span class="line"><span style="color:#e1e4e8;">调模型、编排 Agent、RAG 检索    ←→   流式渲染、交互状态、安全兜底展示</span></span>
<span class="line"><span style="color:#e1e4e8;">工具调用与权限（服务端）        ←→   越权提示、二次确认 UI</span></span>
<span class="line"><span style="color:#e1e4e8;">成本与限流（服务端）            ←→   配额提示、降级态展示</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">后端（knowledge/backend/AI-Agent）   前端（本目录）</span></span>
<span class="line"><span style="color:#24292e;">─────────────────────────────────────────────────</span></span>
<span class="line"><span style="color:#24292e;">调模型、编排 Agent、RAG 检索    ←→   流式渲染、交互状态、安全兜底展示</span></span>
<span class="line"><span style="color:#24292e;">工具调用与权限（服务端）        ←→   越权提示、二次确认 UI</span></span>
<span class="line"><span style="color:#24292e;">成本与限流（服务端）            ←→   配额提示、降级态展示</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>边界很清楚</strong>：凡是「用户可以绕过前端直接调接口」能造成的风险，都必须在后端解决；前端只负责<strong>体验</strong>和<strong>最后一层展示安全</strong>（转义、CSP、二次确认）。</p><h2 id="后续想补的-按价值" tabindex="-1">后续想补的（按价值） <a class="header-anchor" href="#后续想补的-按价值" aria-label="Permalink to &quot;后续想补的（按价值）&quot;">​</a></h2><ol><li><strong>AI 对话界面开发</strong>：消息状态机（pending / streaming / done / error）、重试与分支、多轮编辑、会话列表</li><li><strong>Generative UI</strong>：让模型返回结构化描述、前端渲染组件（而不是纯文本）</li><li><strong>端侧 AI</strong>：WebGPU / WebNN 跑小模型，隐私与延迟的取舍</li><li><strong>多模态交互</strong>：语音输入输出、图片理解的前端链路</li></ol><h2 id="一句提醒" tabindex="-1">一句提醒 <a class="header-anchor" href="#一句提醒" aria-label="Permalink to &quot;一句提醒&quot;">​</a></h2><p>流式这件事<strong>后端和前端各有一半</strong>：后端要落库、要知道断点在哪；前端要缓冲、要节流渲染、要能续传。只做一半就会出现「看起来在流、其实一断就全丢」的假流式。</p>`,11)]))}const g=e(r,[["render",l]]);export{b as __pageData,g as default};
